package dev.slne.surf.event.werewolf.service

import java.util.UUID

object WerewolfGameManager {

    private val games = mutableMapOf<String, WerewolfService>()

    fun createGame(gameId: String, leaderUuid: UUID): WerewolfService? {
        if (games.containsKey(gameId)) return null
        val game = WerewolfService(gameId)
        game.openLobby(leaderUuid)
        games[gameId] = game
        return game
    }

    fun getGame(gameId: String): WerewolfService? {
        return games[gameId]
    }

    fun removeGame(gameId: String) {
        games.remove(gameId)
    }

    fun getAllGames(): Map<String, WerewolfService> {
        return games.toMap()
    }
}

package dev.slne.surf.event.werewolf.service

import java.util.UUID

object WerewolfGameManager {

    private val games = mutableMapOf<String, WerewolfService>()
    private val playerToGame = mutableMapOf<UUID, String>()

    fun createGame(gameId: String, leaderUuid: UUID): WerewolfService? {
        if (games.containsKey(gameId)) return null
        val game = WerewolfService(gameId)
        game.openLobby(leaderUuid)
        games[gameId] = game
        playerToGame[leaderUuid] = gameId
        return game
    }

    fun getGame(gameId: String): WerewolfService? {
        return games[gameId]
    }

    fun getGameForPlayer(uuid: UUID): WerewolfService? {
        val gameId = playerToGame[uuid] ?: return null
        return getGame(gameId)
    }

    fun removeGame(gameId: String) {
        val game = games[gameId] ?: return
        game.players.keys.forEach { playerToGame.remove(it) }
        games.remove(gameId)
    }

    fun getAllGames(): Map<String, WerewolfService> {
        return games.toMap()
    }

    fun joinGame(gameId: String, uuid: UUID) {
        playerToGame[uuid] = gameId
    }
}

package dev.slne.surf.event.werewolf.commands.subcommands

import dev.jorel.commandapi.kotlindsl.playerExecutor
import dev.jorel.commandapi.kotlindsl.stringArgument
import dev.jorel.commandapi.kotlindsl.subcommand
import dev.slne.surf.api.core.messages.Colors
import dev.slne.surf.api.core.messages.adventure.buildText
import dev.slne.surf.api.core.messages.adventure.sendText
import dev.slne.surf.event.werewolf.service.WerewolfGameManager
import dev.slne.surf.event.werewolf.service.WerewolfJoinResult
import net.kyori.adventure.text.event.ClickEvent
import net.kyori.adventure.text.event.HoverEvent
import net.kyori.adventure.text.format.TextDecoration
import org.bukkit.entity.Player

private fun createClickable(gameId: String) = buildText {
    text("HIER", Colors.VARIABLE_VALUE, TextDecoration.UNDERLINED)
    hoverEvent(HoverEvent.showText(buildText { info("Klicke hier, um der Einladung zu folgen und dem Spiel '$gameId' beizutreten!") }))
    clickEvent(ClickEvent.runCommand("/werewolf join $gameId"))
}

private fun renderWerewolfJoinResult(result: WerewolfJoinResult) = buildText {
    when (result) {
        WerewolfJoinResult.Success -> {
            appendSuccessPrefix()
            success("Du bist dem Werwolf-Spiel erfolgreich beigetreten!")
        }

        WerewolfJoinResult.AlreadyInGame -> {
            appendErrorPrefix()
            error("Du nimmst bereits an diesem Spiel teil.")
        }

        WerewolfJoinResult.AlreadyStarted -> {
            appendErrorPrefix()
            error("Das Spiel läuft bereits, du kannst nicht mehr beitreten.")
        }

        is WerewolfJoinResult.Error -> {
            appendErrorPrefix()
            error("Fehler beim Beitreten: ${result.message}")
        }
    }
}

fun openGameWerewolfCommand() = subcommand("openGame") {
    stringArgument("gameId")
    playerExecutor { player, arguments ->
        val gameId = arguments.get("gameId") as String

        val game = WerewolfGameManager.createGame(gameId, player.uniqueId)
        if (game == null) {
            player.sendText {
                appendErrorPrefix()
                error("Spiel mit ID '$gameId' existiert bereits.")
            }
            return@playerExecutor
        }

        val potentialParticipants = player.getNearbyEntities(20.0, 20.0, 20.0)
            .filterIsInstance<Player>().filter { it != player }

        if (potentialParticipants.isEmpty()) {
            player.sendText {
                appendErrorPrefix()
                error("Es wurden keine Spieler in der Nähe gefunden, die dem Spiel beitreten könnten.")
            }
            return@playerExecutor
        } else {
            player.sendText {
                appendSuccessPrefix()
                success("Es wurden ${potentialParticipants.size} potenzielle Teilnehmer in der Nähe gefunden, die eingeladen werden mitzuspielen.")
            }
        }

        potentialParticipants.forEach { participant ->
            participant.sendText {
                appendInfoPrefix()
                info("Du wurdest von")
                appendSpace()
                variableValue(player.name)
                appendSpace()
                info("eingeladen, dem Werwolf-Spiel '$gameId' beizutreten!")

                appendNewInfoPrefixedLine()
                info("Klicke")
                appendSpace()
                append(createClickable(gameId))
                appendSpace()
                info("um der Einladung zu folgen und dem Spiel beizutreten.")

            }
        }
    }
}

