class PaperMain : SuspendingJavaPlugin() {
override suspend fun onEnableAsync() { werewolfCommand()
val voicechatService = server.servicesManager.load(BukkitVoicechatService::class.java) voicechatService?.registerPlugin(WerewolfVoicechatPlugin()) }
override suspend fun onDisableAsync() { } }
val plugin get() = JavaPlugin.getPlugin(PaperMain::class.java)
fun SurfComponentBuilder.inWerewolfColor(text: Any, vararg decoration: TextDecoration) = coloredComponent(text.toString(), TextColor.color(0, 120, 255), *decoration)

package dev.slne.surf.event.werewolf

import com.github.shynixn.mccoroutine.folia.SuspendingJavaPlugin
import de.maxhenkel.voicechat.api.BukkitVoicechatService
import dev.slne.surf.api.core.messages.builder.SurfComponentBuilder
import dev.slne.surf.event.werewolf.commands.werewolfCommand
import dev.slne.surf.event.werewolf.voicechat.WerewolfVoicechatPlugin
import net.kyori.adventure.text.format.TextColor
import net.kyori.adventure.text.format.TextDecoration
import org.bukkit.plugin.java.JavaPlugin

class PaperMain : SuspendingJavaPlugin() {

    override suspend fun onEnableAsync() {
        werewolfCommand()

        val voicechatService = server.servicesManager.load(BukkitVoicechatService::class.java)
        if (voicechatService != null) {
            val plugin = WerewolfVoicechatPlugin()
            voicechatService.registerPlugin(plugin)

            // Speichere die VoicechatServerApi für später Zugriff
            voicechatService.voicechatServerApi?.let {
                WerewolfVoicechatPlugin.setVoicechatApi(it)
            }
        }
    }

    override suspend fun onDisableAsync() {
    }
}

val plugin get() = JavaPlugin.getPlugin(PaperMain::class.java)

fun SurfComponentBuilder.inWerewolfColor(text: Any, vararg decoration: TextDecoration) =
    coloredComponent(text.toString(), TextColor.color(0, 120, 255), *decoration)

package dev.slne.surf.event.werewolf.commands.subcommands

import dev.jorel.commandapi.kotlindsl.playerExecutor
import dev.jorel.commandapi.kotlindsl.subcommand
import dev.slne.surf.api.core.messages.adventure.sendText
import dev.slne.surf.event.werewolf.service.WerewolfService
import dev.slne.surf.event.werewolf.service.WerewolfStartResult

fun startWerewolfCommand() = subcommand("start") {
    playerExecutor { player, _ ->

        when (val result = WerewolfService.start()) {
            is WerewolfStartResult.Success -> {
                player.sendText {
                    appendSuccessPrefix()
                    success("Das Spiel wurde erfolgreich gestartet!")
                }
            }

            is WerewolfStartResult.NotInLobbyPhase -> {
                player.sendText {
                    appendErrorPrefix()
                    error("Das Spiel läuft bereits.")
                }
            }

            is WerewolfStartResult.NotEnoughPlayers -> {
                player.sendText {
                    appendErrorPrefix()
                    error("Start fehlgeschlagen! Es fehlen noch Spieler.")
                    appendSpace()
                    spacer("(")
                    variableValue(result.current)
                    spacer("/")
                    variableValue(result.required)
                    spacer(")")
                }
            }

            is WerewolfStartResult.Error -> {
                player.sendText {
                    appendErrorPrefix()
                    error("Es ist ein Fehler aufgetreten: ${result.message}")
                }
            }
        }
    }
}

